# Prepare the reduced MPNST example dataset.
#
# The source data were generated by the package author's research group and the
# original study is deposited in EGA under accession EGAS50000001747. This
# script selects cells and genes, retains logcounts and selected annotations,
# reduces each embedding to two dimensions, replaces source sample identifiers
# with generic identifiers, validates the result, and saves the package data.
#
# The upstream processed SingleCellExperiment is not part of this package.
# Run this script from the scOverlay package root, optionally setting the
# SCOVERLAY_MPNST_SOURCE environment variable to its local .RData path.

library(SingleCellExperiment)

source_file <- Sys.getenv(
    "SCOVERLAY_MPNST_SOURCE",
    unset = "../../../DoD/MultiomeAnalysis/cache/sce_clustered_withCellTypes_UMAP.RData"
)
if (!file.exists(source_file)) {
    stop(
        "Source data not found. Set `SCOVERLAY_MPNST_SOURCE` to the source RData file.",
        call. = FALSE
    )
}

source_environment <- new.env(parent = emptyenv())
loaded_objects <- load(source_file, envir = source_environment)
if (!("sce" %in% loaded_objects)) {
    stop("The source RData file must contain an object named `sce`.", call. = FALSE)
}
rna.hvg <- source_environment$sce

# Reproduce the existing sample selection: two Nerve, PNF, and ANF samples and
# three MPNST samples, followed by up to 2,500 cells from each selected sample.
set.seed(42L)
samples_per_type <- c(Nerve = 2L, PNF = 2L, ANF = 2L, MPNST = 3L)
selected_samples_by_type <- lapply(names(samples_per_type), function(sample_type) {
    candidates <- unique(as.character(
        rna.hvg$sample[as.character(rna.hvg$sample_type) == sample_type]
    ))
    candidates <- candidates[!is.na(candidates) & nzchar(candidates)]
    if (length(candidates) < samples_per_type[[sample_type]]) {
        stop(
            "Not enough samples of type `", sample_type, "` in the source SCE.",
            call. = FALSE
        )
    }
    return(sample(candidates, size = samples_per_type[[sample_type]]))
})
selected_samples <- unlist(selected_samples_by_type, use.names = FALSE)

selected_sample_types <- vapply(selected_samples, function(sample_id) {
    sample_types <- unique(as.character(
        rna.hvg$sample_type[as.character(rna.hvg$sample) == sample_id]
    ))
    if (length(sample_types) != 1L || is.na(sample_types)) {
        stop("Each selected sample must map to exactly one sample type.", call. = FALSE)
    }
    return(sample_types)
}, character(1))
within_type_index <- ave(
    seq_along(selected_samples),
    selected_sample_types,
    FUN = seq_along
)
generic_sample_ids <- paste0(selected_sample_types, within_type_index)
if (anyDuplicated(selected_samples) || anyDuplicated(generic_sample_ids)) {
    stop("Source or generic sample identifiers are not unique.", call. = FALSE)
}
if (any(generic_sample_ids %in% selected_samples)) {
    stop(
        "A generic sample identifier coincides with a source sample identifier; ",
        "change the naming scheme to ensure pseudonymization.",
        call. = FALSE
    )
}
sample_id_map <- stats::setNames(generic_sample_ids, selected_samples)

cells_to_keep <- unlist(lapply(selected_samples, function(sample_id) {
    cell_indices <- which(as.character(rna.hvg$sample) == sample_id)
    n_cells <- min(2500L, length(cell_indices))
    sample(cell_indices, size = n_cells)
}), use.names = FALSE)
sce_mpnst_example <- rna.hvg[, cells_to_keep]

# Retain only log-normalized expression values; raw counts are not distributed.
SummarizedExperiment::assays(sce_mpnst_example) <-
    SummarizedExperiment::assays(sce_mpnst_example)["logcounts"]

genes_to_keep <- c(
    # NF1 / MPNST progression and recurrently altered pathways
    "NF1", "CDKN2A", "CDKN2B", "TP53", "RB1",
    "SUZ12", "EED", "EZH2", "EGFR", "PDGFRA",
    "MET", "SOX9", "TWIST1", "JUN", "FOS", "PRRX1",

    # Schwann cell / neural crest / peripheral nerve identity
    "SOX10", "S100B", "MPZ", "MBP", "PLP1",
    "PMP22", "NGFR", "ERBB3", "GFAP", "GAP43",
    "FOXD3", "NES", "NCAM1", "L1CAM", "CDH19",

    # Proliferation / cell cycle
    "MKI67", "TOP2A", "PCNA", "MCM2", "MCM5",
    "CCNB1", "CDK1",

    # Mesenchymal / EMT-like / extracellular matrix / fibroblast
    "VIM", "FN1", "COL1A1", "COL1A2", "COL3A1",
    "DCN", "LUM", "ACTA2", "TAGLN", "POSTN",

    # Immune cells
    "PTPRC", "CD3D", "CD3E", "CD4", "CD8A",
    "MS4A1", "CD79A", "NKG7", "GNLY", "LYZ",
    "CD14", "FCGR3A", "CD68", "CD163", "MRC1",
    "TPSAB1",

    # Endothelial / pericyte / vascular
    "PECAM1", "VWF", "KDR", "RGS5", "PDGFRB",

    # Broadly expressed / useful controls
    "MALAT1", "B2M", "ACTB", "GAPDH", "RPLP0",
    "EEF1A1", "TUBB"
)
genes_present <- genes_to_keep[genes_to_keep %in% rownames(sce_mpnst_example)]
genes_missing <- setdiff(genes_to_keep, rownames(sce_mpnst_example))
if (length(genes_missing) > 0L) {
    warning(
        "These requested genes were not found and will be skipped: ",
        paste(genes_missing, collapse = ", "),
        call. = FALSE
    )
}
sce_mpnst_example <- sce_mpnst_example[genes_present, , drop = FALSE]

columns_to_keep <- c(
    "lib_size", "n_detected", "mito_percent", "sample", "sample_type",
    "sizeFactor", "scDblFinder.score", "scDblFinder.class", "label",
    "celltype", "celltype.main"
)
SummarizedExperiment::colData(sce_mpnst_example) <-
    SummarizedExperiment::colData(sce_mpnst_example)[, columns_to_keep]
colnames(SummarizedExperiment::colData(sce_mpnst_example))[9L] <- "cluster"

# Retain UMAP, TSNE, and PCA when available, using their first two dimensions.
reduced_dimensions_to_keep <- intersect(
    c("UMAP", "TSNE", "PCA"),
    SingleCellExperiment::reducedDimNames(sce_mpnst_example)
)
reduced_dimensions_to_keep <- reduced_dimensions_to_keep[vapply(
    reduced_dimensions_to_keep,
    function(reduced_dimension) {
        ncol(SingleCellExperiment::reducedDim(
            sce_mpnst_example,
            reduced_dimension
        )) >= 2L
    },
    logical(1)
)]
if (!("TSNE" %in% reduced_dimensions_to_keep)) {
    stop("The processed SCE must provide a two-dimensional TSNE for the package examples.",
         call. = FALSE)
}
SingleCellExperiment::reducedDims(sce_mpnst_example) <- S4Vectors::SimpleList(
    lapply(reduced_dimensions_to_keep, function(reduced_dimension) {
        SingleCellExperiment::reducedDim(
            sce_mpnst_example,
            reduced_dimension
        )[, 1:2, drop = FALSE]
    })
)
names(SingleCellExperiment::reducedDims(sce_mpnst_example)) <-
    reduced_dimensions_to_keep

S4Vectors::metadata(sce_mpnst_example) <- list()
SummarizedExperiment::rowData(sce_mpnst_example) <-
    SummarizedExperiment::rowData(sce_mpnst_example)[, c(1L, 2L)]

# Replace sample identifiers and cell-name prefixes without altering the 10x
# barcode suffix or cell order.
original_sample_ids <- as.character(sce_mpnst_example$sample)
renamed_sample_ids <- unname(sample_id_map[original_sample_ids])
if (anyNA(renamed_sample_ids)) {
    stop("Some cells could not be matched to a generic sample identifier.", call. = FALSE)
}

original_cell_names <- colnames(sce_mpnst_example)
original_prefixes <- paste0(original_sample_ids, "_")
if (any(!startsWith(original_cell_names, original_prefixes))) {
    stop("A cell name does not start with its known sample identifier.", call. = FALSE)
}
barcode_suffixes <- substring(
    original_cell_names,
    first = nchar(original_prefixes) + 1L
)
if (anyNA(barcode_suffixes) || any(!nzchar(barcode_suffixes))) {
    stop("One or more source cell names have an empty barcode suffix.", call. = FALSE)
}
new_cell_names <- paste0(renamed_sample_ids, "_", barcode_suffixes)

expression_before_renaming <- lapply(
    SummarizedExperiment::assayNames(sce_mpnst_example),
    function(assay_name) {
        unname(SummarizedExperiment::assay(sce_mpnst_example, assay_name))
    }
)
coordinates_before_renaming <- lapply(
    SingleCellExperiment::reducedDimNames(sce_mpnst_example),
    function(reduced_dimension) {
        unname(SingleCellExperiment::reducedDim(
            sce_mpnst_example,
            reduced_dimension
        ))
    }
)
other_coldata_names <- setdiff(
    colnames(SummarizedExperiment::colData(sce_mpnst_example)),
    "sample"
)
other_coldata_before_renaming <- lapply(other_coldata_names, function(column_name) {
    SummarizedExperiment::colData(sce_mpnst_example)[[column_name]]
})
rowdata_before_renaming <- SummarizedExperiment::rowData(sce_mpnst_example)
metadata_before_renaming <- S4Vectors::metadata(sce_mpnst_example)
feature_names_before_renaming <- rownames(sce_mpnst_example)

sce_mpnst_example$sample <- factor(
    renamed_sample_ids,
    levels = unname(sample_id_map)
)
sce_mpnst_example$sample <- droplevels(sce_mpnst_example$sample)
colnames(sce_mpnst_example) <- new_cell_names

# Validate identifiers, dimensions, and alignment before saving. The transient
# source-to-generic mapping is not stored in the distributed object.
expected_sample_ids <- unlist(lapply(names(samples_per_type), function(sample_type) {
    paste0(sample_type, seq_len(samples_per_type[[sample_type]]))
}), use.names = FALSE)
if (!identical(levels(sce_mpnst_example$sample), expected_sample_ids)) {
    stop("Generic sample identifiers or their levels are incorrect.", call. = FALSE)
}
if (anyDuplicated(colnames(sce_mpnst_example))) {
    stop("Renamed cell identifiers must be unique.", call. = FALSE)
}
if (!identical(
    rownames(SummarizedExperiment::colData(sce_mpnst_example)),
    colnames(sce_mpnst_example)
)) {
    stop("colData row names are not aligned with cell identifiers.", call. = FALSE)
}
if (!identical(rownames(sce_mpnst_example), feature_names_before_renaming)) {
    stop("Feature names or ordering changed during renaming.", call. = FALSE)
}

for (assay_index in seq_along(expression_before_renaming)) {
    assay_name <- SummarizedExperiment::assayNames(sce_mpnst_example)[[assay_index]]
    current_assay <- SummarizedExperiment::assay(sce_mpnst_example, assay_name)
    if (!identical(unname(current_assay), expression_before_renaming[[assay_index]])) {
        stop("Expression values or cell ordering changed during renaming.", call. = FALSE)
    }
    if (!identical(colnames(current_assay), colnames(sce_mpnst_example))) {
        stop("Assay column names are not aligned with cell identifiers.", call. = FALSE)
    }
}

for (dimension_index in seq_along(coordinates_before_renaming)) {
    reduced_dimension <-
        SingleCellExperiment::reducedDimNames(sce_mpnst_example)[[dimension_index]]
    current_coordinates <- SingleCellExperiment::reducedDim(
        sce_mpnst_example,
        reduced_dimension
    )
    if (!identical(
        unname(current_coordinates),
        coordinates_before_renaming[[dimension_index]]
    )) {
        stop("Reduced-dimension coordinates or cell ordering changed during renaming.", call. = FALSE)
    }
    if (!identical(rownames(current_coordinates), colnames(sce_mpnst_example))) {
        stop("Reduced-dimension row names are not aligned with cell identifiers.", call. = FALSE)
    }
}

for (column_index in seq_along(other_coldata_names)) {
    column_name <- other_coldata_names[[column_index]]
    current_values <- SummarizedExperiment::colData(sce_mpnst_example)[[column_name]]
    if (!identical(
        current_values,
        other_coldata_before_renaming[[column_index]]
    )) {
        stop("Cell metadata changed during renaming.", call. = FALSE)
    }
}
if (!identical(
    SummarizedExperiment::rowData(sce_mpnst_example),
    rowdata_before_renaming
)) {
    stop("rowData changed during renaming.", call. = FALSE)
}
if (!identical(
    S4Vectors::metadata(sce_mpnst_example),
    metadata_before_renaming
)) {
    stop("Object metadata changed during renaming.", call. = FALSE)
}

collect_character_values <- function(value) {
    if (is.factor(value)) {
        return(c(as.character(value), levels(value)))
    }
    if (is.character(value)) {
        return(value)
    }
    if (inherits(value, "DataFrame")) {
        return(unlist(lapply(as.list(value), collect_character_values), use.names = FALSE))
    }
    if (is.list(value)) {
        return(unlist(lapply(value, collect_character_values), use.names = FALSE))
    }
    return(character())
}

object_strings <- c(
    rownames(sce_mpnst_example),
    colnames(sce_mpnst_example),
    collect_character_values(SummarizedExperiment::colData(sce_mpnst_example)),
    collect_character_values(SummarizedExperiment::rowData(sce_mpnst_example)),
    collect_character_values(S4Vectors::metadata(sce_mpnst_example)),
    unlist(lapply(SummarizedExperiment::assays(sce_mpnst_example), dimnames), use.names = FALSE),
    unlist(lapply(SingleCellExperiment::reducedDims(sce_mpnst_example), dimnames), use.names = FALSE)
)
# Match complete sample labels and sample-prefixed cell IDs. Substring searches
# can falsely flag a generic name (e.g. PNF1) when source IDs overlap it.
original_ids_remaining <- vapply(selected_samples, function(sample_id) {
    any(object_strings == sample_id, na.rm = TRUE) ||
        any(startsWith(object_strings, paste0(sample_id, "_")), na.rm = TRUE)
}, logical(1))
if (any(original_ids_remaining)) {
    stop("Original sample identifiers remain in the prepared object.", call. = FALSE)
}

dir.create("data", showWarnings = FALSE)
save(sce_mpnst_example, file = "data/sce_mpnst_example.rda", compress = "xz")
message("Saved data/sce_mpnst_example.rda")
